+test("findByTag matches tags after the first tag", async () => {
+  const original = (await fetchItems())[0];
+  try {
+    await saveItem({ ...original, tags: ["dry", "grain", "staple"] });
+    for (const tag of ["dry", "grain", "staple"]) {
+      const items = await findByTag(tag);
+      assert.deepEqual(items.map((item) => item.id), [original.id]);
+    }
+    assert.deepEqual(await findByTag("gra"), []);
+  } finally {
+    await saveItem(original);
+  }
+});
